-- =============================================================================
-- Migration V15: Sự cố trong quá trình vận chuyển
-- Tables: incidents
-- So với ERD: thêm resolved_by, updated_at; status varchar + Java enum
-- =============================================================================
CREATE TABLE IF NOT EXISTS "incidents" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "booking_id" int NOT NULL,
  "schedule_id" int,
  "reported_by" bigint,
  "incident_type" varchar(100) NOT NULL,
  "description" text NOT NULL,
  "damage_cost" decimal(12,2) NOT NULL DEFAULT 0,
  "status" varchar(20) NOT NULL DEFAULT 'REPORTED',
  "resolution_note" text,
  "reported_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "resolved_at" timestamp,
  "resolved_by" bigint,
  "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_incidents_booking FOREIGN KEY ("booking_id") REFERENCES "bookings" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_incidents_schedule FOREIGN KEY ("schedule_id") REFERENCES "moving_schedules" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_incidents_reported_by FOREIGN KEY ("reported_by") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT fk_incidents_resolved_by FOREIGN KEY ("resolved_by") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT chk_incidents_status CHECK (status IN ('REPORTED', 'INVESTIGATING', 'RESOLVED', 'REJECTED')),
  CONSTRAINT chk_incidents_damage_cost CHECK (damage_cost >= 0),
  CONSTRAINT chk_incidents_closed CHECK (status NOT IN ('RESOLVED', 'REJECTED') OR (resolved_at IS NOT NULL AND resolution_note IS NOT NULL))
);
CREATE INDEX IF NOT EXISTS idx_incidents_booking ON "incidents" ("booking_id");
CREATE INDEX IF NOT EXISTS idx_incidents_schedule ON "incidents" ("schedule_id");
CREATE INDEX IF NOT EXISTS idx_incidents_status_reported ON "incidents" ("status", "reported_at");
